import{_ as h,o as i,c as a,a5 as t}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"FR 3.5.3 — Ghi nhận thỏa thuận bên ngoài và chỉnh gói trước triển khai","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-3-request-media-package/spec.md","filePath":"feature/media-package-campaign/3-5-3-request-media-package/spec.md"}'),e={name:"feature/media-package-campaign/3-5-3-request-media-package/spec.md"};function c(r,n,g,o,l,u){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="fr-3-5-3-—-ghi-nhan-thoa-thuan-ben-ngoai-va-chinh-goi-truoc-trien-khai" tabindex="-1">FR 3.5.3 — Ghi nhận thỏa thuận bên ngoài và chỉnh gói trước triển khai <a class="header-anchor" href="#fr-3-5-3-—-ghi-nhan-thoa-thuan-ben-ngoai-va-chinh-goi-truoc-trien-khai" aria-label="Permalink to &quot;FR 3.5.3 — Ghi nhận thỏa thuận bên ngoài và chỉnh gói trước triển khai&quot;">​</a></h1><p>Cập nhật BA 2026-11-05. Flow Client request-change/Agency counter-offer trong hệ thống đã được thay bằng <a href="./../guest-sharing-manager-led/spec.html">hành trình Manager quản lý</a>.</p><h2 id="muc-tieu" tabindex="-1">Mục tiêu <a class="header-anchor" href="#muc-tieu" aria-label="Permalink to &quot;Mục tiêu&quot;">​</a></h2><p>Manager dùng kết quả trao đổi bên ngoài với Client để tạo/cập nhật gói workspace. Khách được xem gói quảng bá và trao đổi với Agency trước khi được mời vào làm việc.</p><h2 id="tieu-chi-nghiem-thu" tabindex="-1">Tiêu chí nghiệm thu <a class="header-anchor" href="#tieu-chi-nghiem-thu" aria-label="Permalink to &quot;Tiêu chí nghiệm thu&quot;">​</a></h2><ul><li>Đàm phán/chốt gói diễn ra bên ngoài hệ thống. Không yêu cầu lượt đề xuất, phản hồi hay chấp nhận của Client trên Web.</li><li>Manager chọn gói Agency để tùy chỉnh hoặc nhập mới trong workspace mình quản lý.</li><li>Lưu gói hợp lệ tạo/cập nhật cùng Campaign DRAFT và task theo gói. Không tạo thêm Campaign khi lưu lại.</li><li>Trước triển khai, Manager được sửa gói. Hạng mục không đổi giữ định danh, người phụ trách, giám sát, brief/deadline, subtask và bình luận đã nhập.</li><li>Thêm/giảm/đổi hạng mục phải đồng bộ kế hoạch/task an toàn, hiển thị tác động và lấy xác nhận cần thiết của Manager. Không tự xóa dữ liệu liên quan để khớp số lượng.</li><li>Chặn lưu hoặc triển khai khi có xung đột phiên bản/trạng thái hay chưa đồng bộ xong. Retry không sinh task trùng.</li><li>Từ lúc triển khai cố định bản gói/kế hoạch của lượt đó, cho retry trên cùng bản. Gói đã triển khai được khóa.</li><li>Góp ý của Client về Campaign là comment riêng. Comment không thay điều khoản gói hoặc tạo lượt request-change.</li><li>UI có trường nhập rõ ràng, lựa chọn nhanh hiện hành, lỗi tại trường, xác nhận tác động, vi/en và light/dark.</li></ul><h2 id="lich-su-va-tuong-thich" tabindex="-1">Lịch sử và tương thích <a class="header-anchor" href="#lich-su-va-tuong-thich" aria-label="Permalink to &quot;Lịch sử và tương thích&quot;">​</a></h2><p>Bảo toàn lịch sử đàm phán cũ để truy vết. Cách hiển thị dữ liệu legacy và xử lý endpoint request-change/counter-offer cũ phải được thống nhất khi lập kế hoạch API/DB. Không tạo sự kiện hoặc lượt đồng ý giả cho Client.</p>',8)])])}const m=h(e,[["render",c]]);export{s as __pageData,m as default};
